<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';require_get();$user=api_user();api_rate_limit($user,'hunts.list',60,60);$s=db()->prepare("SELECT h.id,h.title,h.slug,h.description,h.rules,h.featured_image,h.start_at,h.end_at,h.activation_fee,h.status,a.status activation_status,a.activated_at FROM hunts h LEFT JOIN hunt_user_activations a ON a.hunt_id=h.id AND a.user_id=? WHERE h.status='ACTIVE' AND NOW() BETWEEN h.start_at AND h.end_at ORDER BY h.start_at,h.id");$s->execute([$user['id']]);json_response(true,'Active hunts',['items'=>$s->fetchAll()]);
